<nav aria-label="Application Steps" class="mb-4">
    <ol class="step-indicator d-flex list-unstyled justify-content-between p-0 m-0">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var isActive = step == CurrentStep;
            var isCompleted = step < CurrentStep;
            var isFuture = step > CurrentStep;

            <li class="step-item flex-fill text-center @(isActive ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "future" : "")">
                @if (isCompleted)
                {
                    <button class="btn btn-link step-btn p-0 text-decoration-none w-100"
                            @onclick="() => OnStepClicked.InvokeAsync(step)">
                        <span class="step-circle bg-success text-white">✓</span>
                        <span class="step-label d-block small mt-1 text-success fw-semibold">@StepNames[step - 1]</span>
                    </button>
                }
                else
                {
                    <div class="w-100">
                        <span class="step-circle @(isActive ? "bg-primary text-white" : "bg-secondary text-white opacity-50")">@step</span>
                        <span class="step-label d-block small mt-1 @(isActive ? "text-primary fw-semibold" : "text-muted")">@StepNames[step - 1]</span>
                    </div>
                }
            </li>
        }
    </ol>
</nav>

