@page "/apply"
@rendermode InteractiveServer

@using sv_3a4e2baf89404cb48c2799e21e06525e.Components.JobApplication
@using sv_3a4e2baf89404cb48c2799e21e06525e.Models

@inject IApplicationService AppService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="text-center mb-4">Job Application</h2>

    <StepIndicator CurrentStep="currentStep" OnStepClicked="GoToStep" />

    <div class="mt-4">
        @switch (currentStep)
        {
            case 1:
                <PersonalInfoStep Model="personalInfo"
                                  ApplicationService="AppService"
                                  OnNext="NextStep" />
                break;
            case 2:
                <WorkHistoryStep Entries="workEntries"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;
            case 3:
                <ReferencesStep References="references"
                                OnNext="NextStep"
                                OnBack="PreviousStep" />
                break;
            case 4:
                <CoverLetterStep @bind-CoverLetter="coverLetter"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;
            case 5:
                <ReviewStep Personal="personalInfo"
                            WorkEntries="workEntries"
                            References="references"
                            CoverLetter="@coverLetter"
                            OnBack="PreviousStep"
                            OnEditStep="GoToStep"
                            OnSubmit="SubmitApplication"
                            IsSubmitting="isSubmitting"
                            IsSubmitted="isSubmitted"
                            ApplicationId="applicationId"
                            ErrorMessage="@submitError" />
                break;
        }
    </div>
</div>

@code {
    private int currentStep = 1;

    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = [new()];
    private List<ReferenceModel> references = [new(), new()];
    private string coverLetter = "";

    private bool isSubmitting;
    private bool isSubmitted;
    private int? applicationId;
    private string? submitError;

    private void NextStep() => currentStep++;

    private void PreviousStep() => currentStep--;

    private void GoToStep(int step)
    {
        if (step < currentStep)
            currentStep = step;
    }

    private async Task SubmitApplication()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var application = new JobApplication(
                personalInfo.ToRecord(),
                new WorkHistory(workEntries.Select(e => e.ToRecord()).ToList()),
                references.Select(r => r.ToRecord()).ToList(),
                coverLetter
            );

            applicationId = await AppService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

.step-indicator {
    counter-reset: step;
}

.step-item {
    position: relative;
}

.step-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    font-weight: 600;
    font-size: 0.875rem;
}

.step-btn {
    color: inherit;
    border: none;
    cursor: pointer;
}

.step-btn:hover .step-circle {
    opacity: 0.8;
}

.step-item:not(:last-child)::after {
    content: '';
    position: absolute;
    top: 18px;
    left: calc(50% + 22px);
    width: calc(100% - 44px);
    height: 2px;
    background-color: #dee2e6;
    z-index: 0;
}

.step-item.completed:not(:last-child)::after {
    background-color: #198754;
}

